package com.xiaoboluo.d2r;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

// One Build for the Deck's Build tab: a target plan for one class, read from assets/builds/<id>.json (our own short summaries; each
// links the community guide it follows). The JSON is generated by dm/android/tools/gen_build_guides.py: edit the plans there.
// Without Android types (tested by BuildPlanTest).
//
// A Build is a list of Stages, each a level band ending at `to` (the last one has no end). A stage holds:
//   skills  ordered steps {"skill": skills.txt *Id, "to": base level}. A stage carries on from the one before it, unless it is marked
//           "respec": then the plan starts over from that stage (the game's respec resets every point).
//   stats   ordered rules {"stat": "str"|"dex"|"vit"|"ene", ...} with "to": N (spend until the base value is N), "gear": true (enough
//           to wear the gear: not checkable, shown as a reminder) or "rest": true (everything left).
//   gear    {"slot": text, "items": [names], "note": text}. An item is its English game name ("Harlequin Crest", a runeword such as
//           "Spirit"), optionally "|base" ("Spirit|Crystal Sword"); names are shown in the game's language when the import pack has
//           them (ItemNames), else as written. No items: just the note under the slot heading ("Runes": where to farm them).
//   tips    short lines of our own, shown under Skills; "gearTips" under Gear and "bpTips" under Breakpoints (both optional).
// In notes and tips, "[Stealth]" names a game item: shown in the game's language, a runeword with its runes ("Stealth (Tal Eth)").
// Build-wide: "merc" (type and gear like a stage's), "breakpoints" ({"fcr": [table], "fcrTarget": N, "fhr": [table], "fhrTarget": N}),
// "after20" (skill ids to push past 20 once a Rift has raised the cap), "links" ([{"title", "url"}]; the first is the full guide).
final class BuildGuide {
    static final String[] CLASS_CODE = { "ama", "sor", "nec", "pal", "bar", "dru", "ass", "war" };   // charstats.txt row order
    static final String[] STAT_CODE = { "str", "dex", "vit", "ene" };

    static final class Step { final int skill, to; Step(int skill, int to) { this.skill = skill; this.to = to; } }

    static final class StatRule {
        static final int TO = 0, GEAR = 1, REST = 2;
        final int stat, kind, to;
        final String note;
        StatRule(int stat, int kind, int to, String note) { this.stat = stat; this.kind = kind; this.to = to; this.note = note; }
    }

    static final class Gear {
        final String slot, note;
        final List<String> items;
        Gear(String slot, List<String> items, String note) { this.slot = slot; this.items = items; this.note = note; }
    }

    static final class Stage {
        final String name;
        final int to;          // last character level of this stage; Integer.MAX_VALUE for the last stage
        final boolean respec;
        final List<Step> skills;
        final List<StatRule> stats;
        final List<Gear> gear;
        final List<String> tips, gearTips, bpTips;
        Stage(String name, int to, boolean respec, List<Step> skills, List<StatRule> stats, List<Gear> gear, List<String> tips,
              List<String> gearTips, List<String> bpTips) {
            this.name = name; this.to = to; this.respec = respec; this.skills = skills; this.stats = stats; this.gear = gear; this.tips = tips;
            this.gearTips = gearTips; this.bpTips = bpTips;
        }
    }

    static final class Link { final String title, url; Link(String title, String url) { this.title = title; this.url = url; } }

    final String id, name, summary, mercType, mercNote;
    final int cls;
    final List<Stage> stages;
    final List<Gear> merc;
    final List<Link> links;
    final int[] fcr, fhr, after20;
    final int fcrTarget, fhrTarget;

    private BuildGuide(String id, String name, String summary, int cls, List<Stage> stages, String mercType, String mercNote, List<Gear> merc,
                       List<Link> links, int[] fcr, int fcrTarget, int[] fhr, int fhrTarget, int[] after20) {
        this.id = id; this.name = name; this.summary = summary; this.cls = cls; this.stages = stages; this.mercType = mercType;
        this.mercNote = mercNote; this.merc = merc; this.links = links; this.fcr = fcr; this.fcrTarget = fcrTarget; this.fhr = fhr;
        this.fhrTarget = fhrTarget; this.after20 = after20;
    }

    // ---- reading ----
    static BuildGuide parse(String json) {
        Map<String, Object> o = obj(MiniJson.parse(json), "build");
        String id = str(o, "id", null), name = str(o, "name", null), cl = str(o, "class", null);
        int cls = indexOf(CLASS_CODE, cl);
        if (id == null || name == null || cls < 0) throw new IllegalArgumentException("build: needs id, name and a class (" + cl + ")");
        List<Stage> stages = new ArrayList<>();
        List<Object> raw = list(o.get("stages"));
        if (raw.isEmpty()) throw new IllegalArgumentException(id + ": no stages");
        int last = 0;
        for (int k = 0; k < raw.size(); k++) {
            Map<String, Object> s = obj(raw.get(k), id + " stage " + k);
            int to = k == raw.size() - 1 ? Integer.MAX_VALUE : num(s, "to", -1);
            if (to <= last) throw new IllegalArgumentException(id + " stage " + k + ": \"to\" must rise (got " + to + ")");
            last = to;
            List<Step> steps = new ArrayList<>();
            for (Object x : list(s.get("skills"))) {
                Map<String, Object> st = obj(x, id + " skill step");
                steps.add(new Step(num(st, "skill", -1), num(st, "to", 1)));
            }
            List<StatRule> stats = new ArrayList<>();
            for (Object x : list(s.get("stats"))) {
                Map<String, Object> r = obj(x, id + " stat rule");
                int stat = indexOf(STAT_CODE, str(r, "stat", ""));
                if (stat < 0) throw new IllegalArgumentException(id + ": unknown stat " + r.get("stat"));
                int kind = Boolean.TRUE.equals(r.get("rest")) ? StatRule.REST : Boolean.TRUE.equals(r.get("gear")) ? StatRule.GEAR : StatRule.TO;
                stats.add(new StatRule(stat, kind, num(r, "to", 0), str(r, "note", "")));
            }
            stages.add(new Stage(str(s, "name", "?"), to, Boolean.TRUE.equals(s.get("respec")), Collections.unmodifiableList(steps),
                                 Collections.unmodifiableList(stats), gear(s.get("gear")), strings(s.get("tips")),
                                 strings(s.get("gearTips")), strings(s.get("bpTips"))));
        }
        Map<String, Object> m = o.get("merc") == null ? Collections.emptyMap() : obj(o.get("merc"), id + " merc");
        Map<String, Object> bp = o.get("breakpoints") == null ? Collections.emptyMap() : obj(o.get("breakpoints"), id + " breakpoints");
        List<Link> links = new ArrayList<>();
        for (Object x : list(o.get("links"))) { Map<String, Object> l = obj(x, id + " link"); links.add(new Link(str(l, "title", ""), str(l, "url", ""))); }
        return new BuildGuide(id, name, str(o, "summary", ""), cls, Collections.unmodifiableList(stages), str(m, "type", ""), str(m, "note", ""),
                              gear(m.get("gear")), Collections.unmodifiableList(links), ints(bp.get("fcr")), num(bp, "fcrTarget", 0),
                              ints(bp.get("fhr")), num(bp, "fhrTarget", 0), ints(o.get("after20")));
    }

    private static List<Gear> gear(Object v) {
        List<Gear> out = new ArrayList<>();
        for (Object x : list(v)) {
            Map<String, Object> g = obj(x, "gear");
            out.add(new Gear(str(g, "slot", ""), strings(g.get("items")), str(g, "note", "")));
        }
        return Collections.unmodifiableList(out);
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> obj(Object v, String what) {
        if (!(v instanceof Map)) throw new IllegalArgumentException(what + ": expected an object");
        return (Map<String, Object>) v;
    }

    @SuppressWarnings("unchecked")
    private static List<Object> list(Object v) { return v instanceof List ? (List<Object>) v : Collections.emptyList(); }

    private static List<String> strings(Object v) {
        List<String> out = new ArrayList<>();
        for (Object x : list(v)) if (x instanceof String) out.add((String) x);
        return Collections.unmodifiableList(out);
    }

    private static int[] ints(Object v) {
        List<Object> l = list(v); int[] out = new int[l.size()];
        for (int i = 0; i < out.length; i++) out[i] = l.get(i) instanceof Double ? ((Double) l.get(i)).intValue() : 0;
        return out;
    }

    private static String str(Map<String, Object> o, String k, String def) { Object v = o.get(k); return v instanceof String ? (String) v : def; }
    private static int num(Map<String, Object> o, String k, int def) { Object v = o.get(k); return v instanceof Double ? ((Double) v).intValue() : def; }
    static int indexOf(String[] a, String s) { for (int i = 0; i < a.length; i++) if (a[i].equals(s)) return i; return -1; }
}
